<?php
declare(strict_types=1);
require __DIR__.'/bootstrap.php';if(empty($_SESSION['admin_id']))redirect('index.php');require_once dirname(__DIR__).'/private/business_documents.php';require_once dirname(__DIR__).'/private/ui.php';
$id=(int)($_GET['id']??0);
if($_SERVER['REQUEST_METHOD']==='POST'){checkCsrf();try{$action=(string)($_POST['action']??'');if($action==='create')$id=offerCreate($pdo,(int)$_SESSION['admin_id'],$_POST,$config);elseif($action==='item')offerItem($pdo,(int)$_SESSION['admin_id'],$id,$_POST);elseif($action==='issue'){if(empty($_POST['confirm']))throw new RuntimeException('Angebot prüfen und bestätigen.');offerIssue($pdo,(int)$_SESSION['admin_id'],$id,(string)($_POST['date']??''));}elseif($action==='convert'){$new=offerConvert($pdo,(int)$_SESSION['admin_id'],$id);redirect('invoice.php?id='.$new);}else throw new RuntimeException('Aktion unbekannt.');}catch(Throwable $e){gszUiError($e);}redirect('offers.php'.($id?'?id='.$id:''));}
$offers=[];$offer=null;$items=[];$customers=[];try{$offers=$pdo->query("SELECT id,number,status,recipient_name FROM invoices WHERE document_kind='offer' ORDER BY id DESC LIMIT 100")->fetchAll();$customers=$pdo->query('SELECT id,name FROM customers ORDER BY name')->fetchAll();if($id){$offer=invGet($pdo,$id);if($offer['document_kind']!=='offer')throw new RuntimeException('Kein Angebot.');$items=invItems($pdo,$id);}}catch(Throwable $e){$_SESSION['app_error']=$e instanceof PDOException?'Dokumenten-Migration v250 erforderlich.':$e->getMessage();}
gszPageStart('Angebote');?><p>Verwendet dieselben Positions-/Betragsfunktionen wie Rechnungen. Freigabe vergibt Angebotsnummer; Übernahme erzeugt einmalig einen Rechnungsentwurf. Keine automatische Rechnungsausstellung oder E-Mail.</p>
<?php if($offer):?><section class="card"><h2><?=e($offer['number']?:'Angebotsentwurf #'.$id)?></h2><p><?=e($offer['recipient_name'].' · '.$offer['status'])?></p><?php foreach($items as $item):?><p><?=e($item['description'].' · '.$item['gross_amount'].' EUR')?></p><?php endforeach?><p>Gesamt <?=e($offer['gross_total'])?> EUR</p><?php if($offer['status']==='draft'):?><form method="post"><?php gszFields('item');?><label>Leistung<input name="description" maxlength="500" required></label><label>Menge<input name="quantity" value="1" required></label><label>Einzelpreis netto EUR<input name="unit_price" required></label><label>USt<select name="tax_rate"><option value="19">19 %</option><option value="7">7 %</option><option value="0">0 % – fachlich prüfen</option></select></label><button>Position hinzufügen</button></form><form method="post"><?php gszFields('issue');?><label>Angebotsdatum<input type="date" name="date" value="<?=date('Y-m-d')?>" required></label><label><input type="checkbox" name="confirm" required> Angaben und Steuerbehandlung geprüft, Angebotsnummer vergeben.</label><button>Angebot freigeben</button></form><?php else:?><p><a href="invoice_export.php?id=<?=$id?>&amp;format=pdf">Angebots-PDF</a></p><form method="post"><?php gszFields('convert');?><button>Einmalig als Rechnungsentwurf übernehmen</button></form><?php endif?></section><?php endif?>
<details class="card"><summary>Neues Angebot</summary><form method="post"><?php gszFields('create');?><label>Kunde<select name="customer_id"><?php foreach($customers as $c):?><option value="<?=(int)$c['id']?>"><?=e($c['name'])?></option><?php endforeach?></select></label><label>Vollständige Empfängeranschrift<textarea name="recipient_address" maxlength="2000" required></textarea></label><button>Angebotsentwurf erstellen</button></form></details><section class="card"><h2>Letzte 100 Angebote</h2><?php foreach($offers as $o):?><p><a href="offers.php?id=<?=(int)$o['id']?>"><?=e($o['number']?:'Entwurf #'.$o['id'])?></a> · <?=e($o['recipient_name'].' · '.$o['status'])?></p><?php endforeach?></section><?php gszPageEnd();?>
